import{_ as i,o as r,c as a,ag as e,j as o}from"./chunks/framework.DoUXNnsN.js";const p=JSON.parse('{"title":"电子制造信息系统全景图","description":"","frontmatter":{"title":"电子制造信息系统全景图","aliases":["系统全景图","制造业信息系统","工厂系统架构"],"tags":["制造业务","地图","系统"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Enterprise_resource_planning","https://en.wikipedia.org/wiki/Manufacturing_execution_system","https://en.wikipedia.org/wiki/Warehouse_management_system","https://en.wikipedia.org/wiki/Laboratory_information_management_system","https://en.wikipedia.org/wiki/Advanced_planning_and_scheduling","https://en.wikipedia.org/wiki/Statistical_process_control","https://en.wikipedia.org/wiki/Product_lifecycle_management","https://www.electronics.org/ipc-2591-connected-factory-exchange-cfx","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":4},"headers":[],"relativePath":"80-电子制造业务/地图/电子制造信息系统全景图.md","filePath":"80-电子制造业务/地图/电子制造信息系统全景图.md"}'),d={name:"80-电子制造业务/地图/电子制造信息系统全景图.md"},n={style:{"overflow-x":"auto"}},l={role:"img","aria-label":"电子制造信息系统关系图",viewBox:"0 0 900 540",width:"100%",style:{"min-width":"720px","max-width":"900px",display:"block",margin:"16px auto"},"font-size":"13"};function s(h,t,c,g,x,S){return r(),a("div",null,[t[1]||(t[1]=e('<blockquote class="callout-warn"><p>⚠ 待核对：每个系统的一句话定义已对照维基百科；但&quot;各系统之间传什么数据、谁是主数据的拥有者、QMS 和设备自动化的职责&quot;这些内容是行业通用做法，来自模型知识，没有逐条联网核实。<strong>不同公司、不同厂商的系统边界差别很大，请以你们公司实际的系统为准，并把不一致的地方告诉我，我来修正。</strong></p></blockquote><blockquote><p>本篇是&quot;电子制造业务&quot;的<strong>总地图</strong>。读完你应该能：说出 ERP、PLM、APS、MES、WMS、QMS、LIMS、SPC 和设备自动化各管什么；看懂一张系统关系图；知道一个业务事件（发料、报工、来料检验）在系统之间怎么流动；明白为什么&quot;主数据&quot;最容易出问题。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>电子制造的信息系统，就是由 ERP（管订单和钱）、PLM（管产品资料）、APS（管排产）、MES（管车间执行）、WMS（管仓库）、QMS 和 LIMS（管质量和检测）、SPC（管过程统计）和设备（真正干活）组成的一个<strong>分层协作的系统群</strong>，本篇用一张图把它们的关系讲清楚。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/80-电子制造业务/地图/ISA-95">ISA-95</a>：知道五个层级，这张全景图就是按它来组织的。</li><li><a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>、<a href="/Encyclopedia/80-电子制造业务/地图/PCB制造流程">PCB制造流程</a>：知道电子厂里实际发生的物理过程，才明白这些系统在管什么。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>刚接触制造业信息化的人最常见的困惑是：这些系统缩写一大堆，到底谁是谁？为什么同一个数据（比如物料编码、BOM）在好几个系统里都有？订单、工单、批次、板码，它们是怎么串起来的？</p><p>这张地图先建立整体印象：每个系统一句话定位，再看数据在它们之间怎么流。以后学任何一个具体系统（<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/WMS/WMS">WMS</a>、<a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a>、<a href="/Encyclopedia/80-电子制造业务/LIMS/LIMS">LIMS</a>……），你都知道它在整张图的什么位置、和谁说话。</p><h2 id="一张图看懂" tabindex="-1">一张图看懂 <a class="header-anchor" href="#一张图看懂" aria-label="Permalink to &quot;一张图看懂&quot;">​</a></h2>',10)),o("div",n,[(r(),a("svg",l,[...t[0]||(t[0]=[e('<title>电子制造信息系统关系图</title><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0,0 L8,4 L0,8 z" fill="currentColor"></path></marker></defs><rect x="10" y="15" width="880" height="120" rx="12" fill="#2563eb" fill-opacity=".07" stroke="#2563eb" stroke-opacity=".35"></rect><rect x="10" y="165" width="880" height="200" rx="12" fill="#7c3aed" fill-opacity=".07" stroke="#7c3aed" stroke-opacity=".35"></rect><rect x="10" y="395" width="880" height="130" rx="12" fill="#0d9488" fill-opacity=".07" stroke="#0d9488" stroke-opacity=".35"></rect><g fill="currentColor"><text x="26" y="45" font-size="15" font-weight="700">Level 4</text><text x="26" y="64">业务计划</text><text x="26" y="195" font-size="15" font-weight="700">Level 3</text><text x="26" y="214">制造运营</text><text x="26" y="425" font-size="15" font-weight="700">Level 0-2</text><text x="26" y="444">设备与现场</text></g><g fill="#2563eb" fill-opacity=".16" stroke="#2563eb" stroke-opacity=".7"><rect x="150" y="40" width="170" height="60" rx="8"></rect><rect x="365" y="40" width="170" height="60" rx="8"></rect><rect x="580" y="40" width="170" height="60" rx="8"></rect></g><g fill="currentColor" text-anchor="middle"><text x="235" y="66" font-size="16" font-weight="700">ERP</text><text x="235" y="86" font-size="11" opacity=".75">订单·采购·财务</text><text x="450" y="66" font-size="16" font-weight="700">PLM</text><text x="450" y="86" font-size="11" opacity=".75">BOM·工程变更</text><text x="665" y="66" font-size="16" font-weight="700">APS</text><text x="665" y="86" font-size="11" opacity=".75">排产计划</text></g><g stroke="currentColor" stroke-width="1.4" fill="none"><path d="M235 100 V118 H665 V100"></path><path d="M450 100 V118"></path><line x1="450" y1="118" x2="450" y2="190" marker-start="url(#arr)" marker-end="url(#arr)"></line></g><text x="462" y="158" fill="currentColor" font-size="11">工单·BOM·排产 ↓　　报工·完工·质量结果 ↑</text><g fill="#7c3aed" fill-opacity=".16" stroke="#7c3aed" stroke-opacity=".7"><rect x="130" y="190" width="170" height="60" rx="8"></rect><rect x="350" y="190" width="200" height="60" rx="8"></rect><rect x="600" y="190" width="170" height="60" rx="8"></rect><rect x="130" y="285" width="170" height="60" rx="8"></rect><rect x="600" y="285" width="170" height="60" rx="8"></rect></g><g fill="currentColor" text-anchor="middle"><text x="215" y="216" font-size="16" font-weight="700">WMS</text><text x="215" y="236" font-size="11" opacity=".75">仓库·物料·库存</text><text x="450" y="216" font-size="16" font-weight="700">MES</text><text x="450" y="236" font-size="11" opacity=".75">工单执行·追溯·防错</text><text x="685" y="216" font-size="16" font-weight="700">QMS</text><text x="685" y="236" font-size="11" opacity=".75">检验·不良·8D</text><text x="215" y="311" font-size="16" font-weight="700">SPC</text><text x="215" y="331" font-size="11" opacity=".75">过程统计控制</text><text x="685" y="311" font-size="16" font-weight="700">LIMS</text><text x="685" y="331" font-size="11" opacity=".75">实验室检测</text></g><g stroke="currentColor" stroke-width="1.4"><line x1="300" y1="225" x2="350" y2="225" marker-start="url(#arr)" marker-end="url(#arr)"></line><line x1="550" y1="225" x2="600" y2="225" marker-start="url(#arr)" marker-end="url(#arr)"></line><line x1="685" y1="250" x2="685" y2="285" marker-start="url(#arr)" marker-end="url(#arr)"></line></g><g fill="currentColor" font-size="10" text-anchor="middle" opacity=".85"><text x="325" y="215">发料·入库</text><text x="575" y="215">检验·判定</text></g><text x="695" y="272" fill="currentColor" font-size="10" opacity=".85">检测委托·结果</text><g stroke="currentColor" stroke-width="1.4" fill="none"><line x1="450" y1="250" x2="450" y2="380" marker-start="url(#arr)" marker-end="url(#arr)"></line><path d="M186 430 V380 H796 V430"></path><path d="M308 430 V380 M430 430 V380 M552 430 V380 M674 430 V380"></path></g><text x="462" y="318" fill="currentColor" font-size="11">配方·程序 ↓　　设备数据 ↑</text><text x="462" y="336" fill="currentColor" font-size="10" opacity=".8">IPC-CFX · OPC UA · Modbus</text><g fill="#0d9488" fill-opacity=".16" stroke="#0d9488" stroke-opacity=".7"><rect x="130" y="430" width="112" height="60" rx="8"></rect><rect x="252" y="430" width="112" height="60" rx="8"></rect><rect x="374" y="430" width="112" height="60" rx="8"></rect><rect x="496" y="430" width="112" height="60" rx="8"></rect><rect x="618" y="430" width="112" height="60" rx="8"></rect><rect x="740" y="430" width="112" height="60" rx="8"></rect></g><g fill="currentColor" text-anchor="middle" font-size="12"><text x="186" y="465">印刷机/SPI</text><text x="308" y="465">贴片机</text><text x="430" y="465">回流焊炉</text><text x="552" y="465">AOI/X-ray</text><text x="674" y="465">ICT/FCT</text><text x="796" y="465">PLC/传感器</text></g>',20)])]))]),t[2]||(t[2]=e('<p><strong>怎么读这张图</strong>：</p><ul><li>上面一层是<strong>计划</strong>：ERP 接订单和管财务，PLM 管产品资料，APS 排产。</li><li>中间一层是<strong>执行</strong>，MES 在中心，WMS、QMS、LIMS、SPC 围绕着它。</li><li>下面一层是<strong>设备</strong>，真正干活的机器和控制器。</li><li>上下之间的箭头是主干：工单、BOM、排产计划<strong>往下</strong>，报工、完工、质量结果<strong>往上</strong>。</li><li>为简洁，图里省略了一些次要连线：比如 WMS 和 QMS 之间的来料检验、SPC 和 QMS 之间的统计报警，见下面的数据流表。</li></ul><h2 id="每个系统一句话" tabindex="-1">每个系统一句话 <a class="header-anchor" href="#每个系统一句话" aria-label="Permalink to &quot;每个系统一句话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>管什么</th><th>在电子厂里的典型例子</th><th>ISA-95 层</th></tr></thead><tbody><tr><td><a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a></td><td>企业主要业务流程的集成管理：订单、采购、库存财务、供应链等；常以一整套集成的应用软件的形式出现</td><td>接客户订单、下生产订单、采购元器件、核算成本</td><td>Level 4</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/PLM/PLM">PLM</a></td><td>产品从诞生到退役整个生命周期的管理，包括 BOM、图纸、工程变更、文档</td><td>管理产品的 BOM 和设计文件，发起工程变更（ECN）</td><td>Level 4</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/APS/APS">APS</a></td><td>高级计划与排程：同时考虑物料、人员、产能的限制，计划并排出生产顺序</td><td>决定哪条线先做哪个工单、什么时候开工</td><td>Level 4</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a></td><td>跟踪和记录原料变成成品的整个过程的计算机系统</td><td>下发工单、过站记录、上料防错、过程参数、追溯</td><td>Level 3</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/WMS/WMS">WMS</a></td><td>组织仓库工作的策略和流程，核心是记录库存的进出和位置</td><td>来料收货、上架、发料、锡膏冷藏管理、湿敏元件管理</td><td>Level 3</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a></td><td>质量管理体系的信息化：检验、不良处理、质量分析、纠正预防</td><td>来料检验 IQC、制程检验 IPQC、不良处理、8D</td><td>Level 3</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/LIMS/LIMS">LIMS</a></td><td>实验室运营的软件：样品登记与追踪、检测任务、仪器、结果和报告</td><td>来料理化分析、可靠性试验、失效分析的样品与报告</td><td>Level 3</td></tr><tr><td><a href="/Encyclopedia/80-电子制造业务/SPC/SPC">SPC</a></td><td>用统计方法监控和控制过程质量，用控制图判断过程是否稳定</td><td>对印刷体积、炉温、尺寸等关键指标画控制图，超出控制限就报警</td><td>Level 3</td></tr><tr><td>设备自动化（<a href="/Encyclopedia/80-电子制造业务/设备自动化/EAP">EAP</a>）</td><td>设备与上位系统的数据交换和控制：采集设备数据、下发配方、远程控制</td><td>通过 IPC-CFX、OPC UA、Modbus 等协议与设备对话</td><td>Level 2 的上方、Level 3 的接口</td></tr></tbody></table><p>注：SPC、QMS 的界线、WMS 与 MES 的界线，在不同厂商的产品里差别很大，有的把几个合在一个产品里。</p><h2 id="数据在系统之间怎么流动" tabindex="-1">数据在系统之间怎么流动 <a class="header-anchor" href="#数据在系统之间怎么流动" aria-label="Permalink to &quot;数据在系统之间怎么流动&quot;">​</a></h2><p>下面是一些常见的业务事件和数据流向（通用做法，具体以你们公司为准）：</p><table tabindex="0"><thead><tr><th>业务事件</th><th>从 → 到</th><th>传什么</th><th>备注</th></tr></thead><tbody><tr><td>客户下单</td><td>ERP</td><td>订单、交期</td><td>起点</td></tr><tr><td>产品资料发布 / 变更</td><td>PLM → ERP、MES</td><td>物料清单（BOM）、工艺信息、工程变更</td><td>版本要对齐</td></tr><tr><td>排产</td><td>ERP → APS → MES</td><td>待生产的工单、排好的计划</td><td>有的公司由 MES 自带排产</td></tr><tr><td>工单下达</td><td>ERP（或 APS）→ MES</td><td>产品型号、数量、BOM、计划时间</td><td></td></tr><tr><td>备料、发料</td><td>MES → WMS；WMS → MES</td><td>物料需求；实际发出的物料批次</td><td>发料批次决定追溯基础</td></tr><tr><td>工单开工、过站</td><td>MES ↔ 设备</td><td>配方、程序下发；过站、设备状态、参数上传</td><td>常通过 IPC-CFX、OPC UA 等</td></tr><tr><td>报工 / 完工</td><td>MES → ERP</td><td>完工数量、不良数量、工时</td><td>用于入库和成本</td></tr><tr><td>成品入库</td><td>MES → WMS → ERP</td><td>入库数量、批次、库位</td><td></td></tr><tr><td>来料检验</td><td>WMS → QMS（LIMS）→ WMS</td><td>到货批次待检；检验结论（合格才能上架或放行）</td><td>需要理化分析时进 LIMS</td></tr><tr><td>过程检验与不良</td><td>MES ↔ QMS</td><td>检验结果、不良代码；质量判定（放行、拦截）</td><td></td></tr><tr><td>过程统计</td><td>MES、设备 → SPC → QMS / MES</td><td>关键指标数据；超限报警、拦截</td><td></td></tr><tr><td>失效分析</td><td>QMS → LIMS → QMS</td><td>样品委托；分析报告</td><td>结论回到 8D / 纠正预防</td></tr></tbody></table><h2 id="一个订单的一生-总览" tabindex="-1">一个订单的一生（总览） <a class="header-anchor" href="#一个订单的一生-总览" aria-label="Permalink to &quot;一个订单的一生（总览）&quot;">​</a></h2><p>用一条主线把上面的系统串起来（只讲大概，详细的完整场景会在后面的&quot;场景&quot;类词条里展开）：</p><ol><li>客户下单，订单进入 <strong>ERP</strong>；</li><li>产品的 BOM 和工艺由 <strong>PLM</strong> 发布，同步到 ERP 和 <strong>MES</strong>；</li><li><strong>APS</strong> 根据订单、物料和产能排出计划；</li><li><strong>ERP/APS</strong> 下达<strong>工单</strong>给 <strong>MES</strong>；</li><li><strong>MES</strong> 向 <strong>WMS</strong> 提出备料需求，<strong>WMS</strong> 发料到线边，并把发出的批次告诉 <strong>MES</strong>；来料如需检验，先经 <strong>QMS</strong>（和 <strong>LIMS</strong>）放行；</li><li>板子上线，<strong>MES</strong> 控制过站、防错，<strong>设备</strong>自动上传参数，<strong>SPC</strong> 监控关键指标，<strong>QMS</strong> 记录检验和不良；</li><li>完工后，<strong>MES</strong> 把完工数量报给 <strong>ERP</strong>，成品由 <strong>WMS</strong> 入库；</li><li>客户收货，若有质量问题，沿着板码从 <strong>MES</strong>、<strong>WMS</strong>、<strong>QMS</strong> 一路追溯。</li></ol><h2 id="主数据-最容易出问题的地方" tabindex="-1">主数据：最容易出问题的地方 <a class="header-anchor" href="#主数据-最容易出问题的地方" aria-label="Permalink to &quot;主数据：最容易出问题的地方&quot;">​</a></h2><p><strong>主数据</strong>是被多个系统共同使用、相对稳定的基础数据：物料编码、BOM、工艺路线、供应商、客户、设备。</p><p>在系统群里，同一份主数据往往在好几个系统里都有一份拷贝。常见的约定是，<strong>每类主数据有一个&quot;拥有者&quot;系统</strong>（比如 BOM 的源头常在 PLM 或 ERP），其他系统从它那里同步。一旦同步出问题，就会出现：</p><ul><li>ERP 里 BOM 已经改版，MES 还在用旧版 → 车间按旧的 BOM 生产；</li><li>同一种物料在两个系统里编码不一致 → 对不上账；</li><li>设备编号、工序名称不统一 → 报表对不上。</li></ul><p>所以做集成时，最先要问的问题不是&quot;接口怎么写&quot;，而是&quot;这份数据的拥有者是谁，变更怎么同步，版本怎么对齐&quot;。</p><h2 id="系统之间怎么连-集成方式" tabindex="-1">系统之间怎么连：集成方式 <a class="header-anchor" href="#系统之间怎么连-集成方式" aria-label="Permalink to &quot;系统之间怎么连：集成方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>通俗解释</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>数据库对接</td><td>一方把数据写进共用的表，另一方来读</td><td>简单直接</td><td>耦合高，表结构一改就出问题</td></tr><tr><td>接口调用（API / Web Service）</td><td>一方调用另一方提供的接口</td><td>清晰、可控</td><td>双方都要开发和维护</td></tr><tr><td>消息队列</td><td>一方把消息放进队列，另一方异步取走</td><td>解耦、可缓冲、可重试</td><td>需要额外的基础设施</td></tr><tr><td>文件交换</td><td>定时生成文件交给对方</td><td>最容易起步</td><td>不实时，容易出错</td></tr></tbody></table><p>据维基百科对 ERP 与车间设备连接方式的描述，常见方式包括：直接集成、数据库集成（车间系统把信息写入数据库，ERP 从暂存表里读取）、专用的接口设备，以及系统集成商的定制开发。</p><h2 id="动手实验-追踪一块板" tabindex="-1">动手实验：追踪一块板 <a class="header-anchor" href="#动手实验-追踪一块板" aria-label="Permalink to &quot;动手实验：追踪一块板&quot;">​</a></h2><p>目标：体会&quot;数据在系统间的足迹&quot;。需要纸笔，可以结合你们公司实际的系统。</p><ol><li>选一块（或一批）已经出货的板子，找到它的<strong>板码</strong>或<strong>批次号</strong>。</li><li>回答：这块板的<strong>订单</strong>是哪张？在哪个系统里查？</li><li>它用的<strong>BOM</strong> 是哪个版本？这个版本从哪来？</li><li>它的<strong>工单</strong>是什么时候下达的？上面的<strong>物料批次</strong>是从哪个仓库发出的？</li><li>它在 SMT 线上过了哪些工站？每个工站的数据存在哪个系统里？</li><li>它有没有被检验、被判过不良、被维修过？记录在哪里？</li><li>画一张表：每一步的<strong>数据</strong>是什么、<strong>存在哪个系统</strong>、<strong>怎么传到下一个系统</strong>。如果有哪一步你答不出来，把问题记下来问同事，那就是你要补的功课。</li></ol><h2 id="常见坑与误区" tabindex="-1">常见坑与误区 <a class="header-anchor" href="#常见坑与误区" aria-label="Permalink to &quot;常见坑与误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>事实</th></tr></thead><tbody><tr><td>&quot;MES 就是生产管理软件，什么都能管&quot;</td><td>MES 管车间执行与追溯；订单、财务归 ERP，仓库归 WMS，质量体系归 QMS，边界因厂商而异</td></tr><tr><td>&quot;买了 ERP 就不需要 MES&quot;</td><td>ERP 通常不管工序级的实时执行和追溯，电子厂对追溯要求高，MES 不可替代</td></tr><tr><td>&quot;各系统各管各的，数据不用统一&quot;</td><td>主数据不统一是集成故障最大的来源</td></tr><tr><td>&quot;接口通了就没问题了&quot;</td><td>还要考虑失败重试、重复数据、时间戳、版本不一致等</td></tr><tr><td>&quot;系统越多越先进&quot;</td><td>重要的是边界清晰、数据一致，不是系统数量</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>来料检验合格后才能上架，涉及哪几个系统？ <strong>答</strong>：WMS（收货、待检、上架）、QMS（检验与判定），必要时 LIMS（理化分析）。检验结论回到 WMS 才能放行。</li><li>工单完工数量，最终由哪个系统确认入账？ <strong>答</strong>：ERP。MES 报工把完工数量交给 ERP，由 ERP 用于入库和成本核算。</li><li>谁负责决定&quot;哪条线先做哪个工单&quot;？ <strong>答</strong>：APS（或 MES 里的排产功能）。ERP 只管订单和交期。</li><li>产品 BOM 变更（ECN）通常从哪个系统发起？变更后要通知哪些系统？ <strong>答</strong>：通常从 PLM（或 ERP）发起，需要同步到 ERP 和 MES，并保证各系统版本一致。</li><li>SPC 控制图报了警，后续动作可能涉及哪些系统？ <strong>答</strong>：通知 MES 拦截或暂停该批次，QMS 记录并发起不良处理。</li><li>为什么说&quot;主数据是集成中最容易出问题的地方&quot;？ <strong>答</strong>：同一份数据（BOM、物料编码）常有多份拷贝，同步不及时或版本不一致，就会导致车间按旧数据生产、账对不上、报表错误。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>电子厂的信息系统是分层的系统群：计划层（ERP、PLM、APS）、执行层（MES、WMS、QMS、LIMS、SPC）、设备层。</li><li>MES 居中，向上对接计划，向下对接设备，向两侧对接仓库和质量。</li><li>工单、BOM、排产往下流；报工、完工、质量结果往上流。</li><li>主数据要有明确的拥有者，同步和版本对齐是集成成败的关键。</li><li>不同公司的系统边界不同，学任何一个系统都要先弄清它在整张图的位置。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/WMS/WMS">WMS</a>、<a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a>、<a href="/Encyclopedia/80-电子制造业务/LIMS/LIMS">LIMS</a>、<a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a>、<a href="/Encyclopedia/80-电子制造业务/APS/APS">APS</a>、<a href="/Encyclopedia/80-电子制造业务/SPC/SPC">SPC</a>、<a href="/Encyclopedia/80-电子制造业务/PLM/PLM">PLM</a>、<a href="/Encyclopedia/80-电子制造业务/设备自动化/EAP">EAP</a>、<a href="/Encyclopedia/80-电子制造业务/地图/ISA-95">ISA-95</a>、<a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>、<a href="/Encyclopedia/80-电子制造业务/地图/PCB制造流程">PCB制造流程</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>维基百科 ERP：<a href="https://en.wikipedia.org/wiki/Enterprise_resource_planning" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Enterprise_resource_planning</a></li><li>维基百科 MES：<a href="https://en.wikipedia.org/wiki/Manufacturing_execution_system" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Manufacturing_execution_system</a></li><li>维基百科 WMS：<a href="https://en.wikipedia.org/wiki/Warehouse_management_system" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Warehouse_management_system</a></li><li>维基百科 LIMS：<a href="https://en.wikipedia.org/wiki/Laboratory_information_management_system" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Laboratory_information_management_system</a></li><li>IPC-2591（CFX）标准介绍：<a href="https://www.electronics.org/ipc-2591-connected-factory-exchange-cfx" target="_blank" rel="noreferrer">https://www.electronics.org/ipc-2591-connected-factory-exchange-cfx</a></li></ul>',32))])}const f=i(d,[["render",s]]);export{p as __pageData,f as default};
